// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    Attacker attacker;

    function setUp() public {
        c = new Reentrance();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1e30);

        vm.deal(address(attacker), amount);
        attacker.deposit(amount);
        attacker.withdraw();

        // General rule: a completed withdrawal transfers exactly the withdrawn
        // balance (the pre-call getBalance) to the counterparty, and afterwards
        // the recorded balance is zero.
        assertTrue(c.getBalance(address(attacker)) == 0 && attacker.totalReceived() == amount);
    }
}

contract Attacker {
    Reentrance public c;
    uint256 public totalReceived;
    bool private entered;

    constructor(Reentrance _c) {
        c = _c;
    }

    function deposit(uint256 amount) external {
        c.addToBalance{value: amount}();
    }

    function withdraw() external {
        c.withdrawBalance();
    }

    receive() external payable {
        totalReceived += msg.value;
        if (!entered) {
            entered = true;
            c.withdrawBalance();
        }
    }
}
